if(typeof require==='function'){var Classy=require('./classy');}var MathUtils=Classy.newClass();MathUtils.classMethods({linearInterpolation:function(a,b,t){return(1.0-t)*a+t*b;},randomRange:function(min,max){return min+Math.random()*(max-min);},randomAroundZero:function(interval){return Math.random()*interval-interval*0.5;},randomArrayEntry:function(array){return array[Math.floor(MathUtils.randomRange(0,array.length))];},randomSign:function(x){return(Math.random()>0.5?x:-x);},getClosestAxis:function(direction){var absX=Math.abs(direction.x);var absY=Math.abs(direction.y);if(absX>=absY){return direction.x>0?{x:1,y:0}:{x:-1,y:0};}else{return direction.y>0?{x:0,y:1}:{x:0,y:-1};}}});if(typeof module==='object'){module.exports=MathUtils;}